#!/usr/bin/env python3
"""Generates ziprCRC32.h: slice-by-8 tables for CRC-32 (IEEE, reflected).

    tools/genCRC.py > ziprCRC32.h
"""
POLY = 0xEDB88320
t = [[0] * 256 for _ in range(8)]
for i in range(256):
    c = i
    for _ in range(8):
        c = (c >> 1) ^ (POLY if c & 1 else 0)
    t[0][i] = c
for k in range(1, 8):
    for i in range(256):
        p = t[k - 1][i]
        t[k][i] = (p >> 8) ^ t[0][p & 0xFF]

print("""/* SPDX-License-Identifier: GPL-2.0 OR BSD-2-Clause */
/* Generated by tools/genCRC.py; do not edit. */
#ifndef ZIPR_CRC32_H
#define ZIPR_CRC32_H

/* CRC-32 tables for slicing by 8 bytes (user space only). */
static const uint32_t ziprCRCTab[8][256] = {""")
for k in range(8):
    print("\t{")
    for i in range(0, 256, 4):
        print("\t\t" + ", ".join("0x%08x" % x for x in t[k][i:i + 4]) + ",")
    print("\t},")
print("""};

#endif /* ZIPR_CRC32_H */""")
